import json,re
d=json.load(open('layout.json'))
def walk(o,out):
    if isinstance(o,dict):
        if o.get('type')=='text' and 'text' in o: out.append(o['text'])
        elif o.get('type')=='codeVoice' and 'code' in o: out.append(o['code'])
        elif o.get('type')=='heading' and 'text' in o: out.append('\n## '+o['text']+'\n')
        elif o.get('type')=='paragraph':
            for c in o.get('inlineContent',[]): walk(c,out)
            out.append('\n\n')
        elif o.get('type')=='listItem':
            out.append('- ')
            for c in o.get('content',[]): walk(c,out)
        else:
            for v in o.values(): walk(v,out)
    elif isinstance(o,list):
        for v in o: walk(v,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
walk(d.get('sections',[]),out)
walk(d.get('abstract',[]),out)
t=''.join(out)
open('layout.txt','w').write(t)
print(len(t))
